const REVIEW_SCHEMA = {
  type: 'object',
  properties: {
    module: { type: 'string' },
    tests_passing: { type: 'boolean' },
    typecheck_passing: { type: 'boolean' },
    test_count: { type: 'number' },
    defects_found_and_fixed: { type: 'array', items: { type: 'string' } },
    remaining_gaps: { type: 'array', items: { type: 'string' } },
    endpoints: { type: 'array', items: { type: 'string' } },
    exported_services: { type: 'array', items: { type: 'string' } },
  },
  required: ['module', 'tests_passing', 'typecheck_passing', 'test_count', 'defects_found_and_fixed', 'remaining_gaps', 'endpoints', 'exported_services'],
}

function reviewPrompt(mod, db, redis, focus) {
  return COMMON + '\n' + 'You are the ADVERSARIAL REVIEWER of module "' + mod + '" (apps/api/src/modules/' + mod + ', tests apps/api/test/integration/' + mod + '*.test.ts) which another agent just implemented; use database ' + db + ' and Redis index ' + redis + '. Goal: find and FIX defects, not describe them. Steps: (1) run typecheck and this module\'s tests; (2) read every file of the module; (3) walk docs/SPEC.md rule by rule for this module and mark each satisfied/violated; (4) attack: ' + focus + '; (5) write failing tests for every violation, fix the code, repeat until green; (6) check the permission on every route, scope → 404, audit rows on every mutation, idempotency on creates, version handling on updates, response schemas, N+1 queries. Return the structured report.'
}

