const CHAINS = {
  a: ['inventory', 'crm'],
  b: ['money', 'construction', 'portal'],
  c: ['documents', 'service', 'reports'],
  d: ['web', 'admin'],
}

const chain = CHAINS[args && args.chain] || []
if (!chain.length) throw new Error('args.chain must be one of a, b, c, d')

if (args.chain === 'a') {
  // inventory and crm are independent: run both pipelines concurrently
  const res = await Promise.all(chain.map(name => pipeline(
    [name],
    () => agent(COMMON + '\n' + MODULES[name].prompt + '\nYour database: ' + MODULES[name].db + ' · your Redis index: ' + MODULES[name].redis + '.', { label: 'implement:' + name, phase: 'Implement', effort: 'high' }),
    () => agent(reviewPrompt(name, MODULES[name].db, MODULES[name].redis, MODULES[name].focus), { label: 'review:' + name, phase: 'Review', effort: 'high', schema: REVIEW_SCHEMA }),
  )))
  return res.map(r => r[0])
}

// dependent chains run strictly in order: implement → review → next module
const results = []
for (const name of chain) {
  const m = MODULES[name]
  await agent(COMMON + '\n' + m.prompt + '\nYour database: ' + m.db + ' · your Redis index: ' + m.redis + '.', { label: 'implement:' + name, phase: 'Implement', effort: 'high' })
  const review = await agent(reviewPrompt(name, m.db, m.redis, m.focus), { label: 'review:' + name, phase: 'Review', effort: 'high', schema: REVIEW_SCHEMA })
  results.push(review)
  log('module ' + name + ' done')
}
return results
